void CTCLight::SetActive(bool active)
{
    Initialised = true;
    Active = active;
    ParentThing->UpdateGraphicAppearance(4);
    ParentThing->SetAsFrameUpdated();
    CTCBase* mesh;
    if (ParentThing->GetInterface(&mesh, 0x5c)) {
        bool replaceable;
        {
